import numpy as np
from vispy import app, gloo
import time
import random

VERT_SHADER = """
#version 120
uniform float u_time;
uniform vec2 u_center;
uniform float u_explosion_time;
attribute vec2 a_position;
attribute vec3 a_color;
attribute float a_angle;
attribute float a_speed;
attribute float a_lifetime;
varying vec3 v_color;
void main()
{
    float t = u_time - u_explosion_time;
    float fade = 1.0 - t / a_lifetime;
    fade = clamp(fade, 0.0, 1.0);
    float r = t * a_speed;
    vec2 pos = u_center + vec2(cos(a_angle), sin(a_angle)) * r;
    gl_Position = vec4(2.0 * pos.x - 1.0, 1.0 - 2.0 * pos.y, 0.0, 1.0);
    gl_PointSize = 3.0 * fade;
    v_color = a_color * fade;
}
"""

FRAG_SHADER = """
#version 120
varying vec3 v_color;
void main()
{
    float dist = length(gl_PointCoord - vec2(0.5, 0.5));
    if (dist > 0.5)
        discard;
    gl_FragColor = vec4(v_color, 1.0);
}
"""

class Canvas(app.Canvas):
    def __init__(self):
        app.Canvas.__init__(self, title='Vispy Fireworks', keys='interactive', size=(800, 600))
        self.program = gloo.Program(VERT_SHADER, FRAG_SHADER)
        self.n_particles = 0
        self.max_particles = 400
        self.particle_dtype = np.dtype([
            ('a_position', np.float32, 2),
            ('a_color',    np.float32, 3),
            ('a_angle',    np.float32, 1),
            ('a_speed',    np.float32, 1),
            ('a_lifetime', np.float32, 1),
        ])
        self.particles = np.zeros(self.max_particles, dtype=self.particle_dtype)
        self.vbo = gloo.VertexBuffer(self.particles)
        self.program.bind(self.vbo)
        self.explosions = []
        self.t0 = time.time()
        self.last_explosion_time = 0
        self.explosion_interval = 1.0
        self.current_explosion = None
        self.timer = app.Timer('auto', connect=self.on_timer, start=True)
        self.show()

    def on_draw(self, event):
        gloo.clear('black')
        now = time.time() - self.t0
        self.program['u_time'] = now
        if self.current_explosion is not None:
            self.program['u_center'] = self.current_explosion['center']
            self.program['u_explosion_time'] = self.current_explosion['time']
            gloo.set_state('additive', depth_test=False)
            self.program.draw('points', self.n_particles)

    def on_resize(self, event):
        gloo.set_viewport(0, 0, *event.size)

    def on_timer(self, event):
        now = time.time() - self.t0
        if (self.current_explosion is None or
            now - self.current_explosion['time'] > 1.0):
            self.create_explosion(now)
        self.update()

    def create_explosion(self, now):
        n = random.randint(80, self.max_particles)
        center = np.array([
            random.uniform(0.15, 0.85),
            random.uniform(0.15, 0.85)
        ], dtype=np.float32)
        colors = np.random.uniform(0.5, 1.0, (n, 3))
        # Make each explosion unique in color and spread
        base_hue = random.uniform(0, 1)
        for i in range(n):
            h = (base_hue + random.uniform(-0.1, 0.1)) % 1.0
            s = random.uniform(0.7, 1.0)
            v = random.uniform(0.8, 1.0)
            colors[i] = self.hsv_to_rgb(h, s, v)
        angles = np.linspace(0, 2 * np.pi, n, endpoint=False) + np.random.uniform(-0.05, 0.05, n)
        speeds = np.random.uniform(0.25, 0.5, n)
        lifetimes = np.random.uniform(0.7, 1.0, n)
        positions = np.tile(center, (n, 1))
        self.particles[:n]['a_position'] = positions
        self.particles[:n]['a_color'] = colors
        self.particles[:n]['a_angle'] = angles
        self.particles[:n]['a_speed'] = speeds
        self.particles[:n]['a_lifetime'] = lifetimes
        self.n_particles = n
        self.vbo.set_data(self.particles[:n])
        self.current_explosion = {'center': center, 'time': now}

    def hsv_to_rgb(self, h, s, v):
        # h,s,v in [0,1]
        i = int(h * 6.0)
        f = (h * 6.0) - i
        p = v * (1.0 - s)
        q = v * (1.0 - f * s)
        t = v * (1.0 - (1.0 - f) * s)
        i = i % 6
        if i == 0:
            return [v, t, p]
        if i == 1:
            return [q, v, p]
        if i == 2:
            return [p, v, t]
        if i == 3:
            return [p, q, v]
        if i == 4:
            return [t, p, v]
        if i == 5:
            return [v, p, q]

    def on_mouse_press(self, event):
        pos = event.pos
        size = self.size
        center = np.array([pos[0] / size[0], pos[1] / size[1]], dtype=np.float32)
        now = time.time() - self.t0
        self.create_explosion_at(center, now)

    def create_explosion_at(self, center, now):
        n = random.randint(80, self.max_particles)
        colors = np.random.uniform(0.5, 1.0, (n, 3))
        base_hue = random.uniform(0, 1)
        for i in range(n):
            h = (base_hue + random.uniform(-0.1, 0.1)) % 1.0
            s = random.uniform(0.7, 1.0)
            v = random.uniform(0.8, 1.0)
            colors[i] = self.hsv_to_rgb(h, s, v)
        angles = np.linspace(0, 2 * np.pi, n, endpoint=False) + np.random.uniform(-0.05, 0.05, n)
        speeds = np.random.uniform(0.25, 0.5, n)
        lifetimes = np.random.uniform(0.7, 1.0, n)
        positions = np.tile(center, (n, 1))
        self.particles[:n]['a_position'] = positions
        self.particles[:n]['a_color'] = colors
        self.particles[:n]['a_angle'] = angles
        self.particles[:n]['a_speed'] = speeds
        self.particles[:n]['a_lifetime'] = lifetimes
        self.n_particles = n
        self.vbo.set_data(self.particles[:n])
        self.current_explosion = {'center': center, 'time': now}

if __name__ == '__main__':
    c = Canvas()
    app.run()
